    def count(self):
        return len(self._orders)

class PricingEngine:
    def __init__(self, tax_rate=0.18, discount_rules=None):
        self._tax_rate = tax_rate
        self._discount_rules = discount_rules or {}
    def set_discount(self, tier, rate):
        # validation
    def discount_for(self, tier):
        # lookup
    def bulk_discount(self, quantity):
        # tiered logic
    def apply_tax(self, amount):
        return round(amount * (1 + self._tax_rate), 2)
    def total_with_tax(self, subtotal, tier):
        # combine discount and tax

class AuditLogger:
    def __init__(self):
        self._log = []
    def log(self, message, level='info'):
        entry = AuditEntry(message, level)
        self._log.append(entry)
    def history(self):
        return [e.format() for e in self._log]
    def clear(self):
        removed = len(self._log)
        self._log = []
        return removed

class NotificationService:
    def __init__(self, host='localhost'):
        self._host = host
        self._sent = []
    def configure(self, host):
        if not host:
            raise ValueError('host bos olamaz')
        self._host = host
    def notify(self, customer, subject):
        notifier = EmailNotifier(self._host)
        result = notifier.send(customer.email, subject)
        self._sent.append(result)
        return result
    def outbox(self):
        return list(self._sent)
    def reset(self):
        count = len(self._sent)
        self._sent = []
        return count

# OrderManager becomes a thin façade that composes these services
class OrderManager:
    def __init__(self):
        self.repo = OrderRepository()
        self.pricing = PricingEngine()
        self.audit = AuditLogger()
        self.notify = NotificationService()
    # delegate methods to the composed services
```

Each new class now has a single responsibility, reducing method count, complexity, and coupling. The façade keeps the original public API if needed, or can be replaced by a more explicit interface.

